.ama__lead-news {
  @include child-top-gutters(calc($gutter / 2));

  // Don't give a top border to the first item in the block.
  // Using ~ instead of :nth-child because d8 inserts a necessary <div> into the rendered block.
  .ama__article-stub ~ .ama__article-stub {
    border-top: 1px solid $gray-50;
    @include gutter($padding-top-half...);
  }
}
